<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {getStudio,type StudioPayload} from './content-studio-api';const payload=ref<StudioPayload|null>(null),q=ref('');onMounted(async()=>payload.value=await getStudio());const places=computed(()=>Object.values(payload.value?.document.places||{}).filter(p=>!q.value||[p.id,p.name.zh,p.name.en,p.region.zh].join(' ').toLowerCase().includes(q.value.toLowerCase())).sort((a,b)=>a.id.localeCompare(b.id)));</script>
<template><div class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">地点</p><h1>按前台卡片维护地点</h1><p>点开卡片后可修改中英文、实用信息、亲子、床车、实地核验和媒体关系。</p></div><RouterLink class="button primary-action" to="/studio/map">从地图查看</RouterLink></div><label class="studio-search"><span>查找地点</span><input v-model="q" placeholder="名称、区域或 WY 编号"></label><div class="studio-place-grid"><RouterLink v-for="p in places" :key="p.id" :to="`/studio/places/${p.id}`" class="studio-place-card"><div class="studio-place-cover"><img v-if="p.photos[0]" :src="`/api/admin/visitor-content/media/${p.photos[0].fileName}`" :alt="p.photos[0].alt.zh"><span v-else>{{p.category.includes('茶')?'茶':p.category.includes('展馆')?'馆':p.category.includes('停车')?'停':p.category.includes('服务')?'服':'地'}}</span></div><article><small>{{p.region.zh||'未填写区域'}} · {{p.id}}</small><h2>{{p.name.zh}}</h2><p>{{p.summary.zh||'未填写简介'}}</p><div class="visual-card-tags"><span v-for="id in p.themeIds" :key="id">{{payload?.document.themes.find(t=>t.id===id)?.name.zh||id}}</span><span v-if="!p.photos.length" class="missing">未设置封面</span></div></article></RouterLink></div></div></template>
